function showOpening(name,options){openingStage=name;openingScreen.setAttribute('name','onboarding/'+name);openingScreen.options={adaptive:true,logo:game.read().logo,gameName:'Huff n Puff Home Run 2',...options};openingFit();game.panelOpen(true);if(!opening.open)opening.showModal();}
function tutorial(){remember=false;showOpening('tutorial',{'Feature title':'','Feature explanation':'',slides:[{title:'Step up to the plate',text:'Choose your bet, then press Play. The wolf swings at a Straw, Wood or Brick Pig. A missed swing ends the round with no win.',image:'assets/official-hnp-v1/wolf.webp'},{title:'Build your return',text:'Numbered hard hats add bet multiples. Multiplier pickups boost the running total. Seagulls halve it and knock the pig downward.',image:game.read().hero},{title:'Land safely',text:'Avoid the woodland pond and broken tree stumps. Land safely on the grass to collect. Turbo changes speed only; autoplay lets you choose rounds and stopping limits.',image:'assets/official-hnp-v1/logo.webp'}]});}
function finishOpening(){openingStage='done';try{localStorage.setItem('huff-home-run-hide-tutorial',remember?'yes':'no')}catch{}opening.close();game.panelOpen(false);game.finishOpening();controller.focusPrimary();}
openingScreen.addEventListener('is-action',e=>{const {action,value}=e.detail;if(openingStage==='sound'&&['sound-on','sound-off'].includes(action)){game.audioPreference(action==='sound-on');let skip=false;try{skip=localStorage.getItem('huff-home-run-hide-tutorial')==='yes'}catch{}if(skip){remember=true;finishOpening()}else tutorial()}if(action==='toggle'&&openingStage==='tutorial')remember=!!value.remember;if(action==='play'&&openingStage==='tutorial')finishOpening();openingFit()});
const compact=matchMedia('(max-width:389px)');
function sync(){const s=game.read();if(openingStage==='loading'&&s.ready)showOpening('sound',{soundHeading:'Hear the ballpark?',soundDescription:'Enjoy music and game effects. Adjust each separately in the menu.'});else if(openingStage==='loading'&&s.loadingError)openingScreen.options={...openingScreen.options,message:s.loadingError};
 const digits=new Intl.NumberFormat(locale.locale(),{style:'currency',currency:s.currency==='RMB'?'CNY':s.currency}).resolvedOptions().maximumFractionDigits;
 const p={playButtonVariant:'play-icon2',region:regional.id==='gb-ukgc'?'UK':'Non UK',difficultyAvailable:false,bonusAvailable:false,'Max Stake':'yes','Extra controls':regional.autoMax||regional.profile.turbo?'yes':'no',currency:locale.currencySymbol(s.currency),locale:locale.locale(),digits,stakeDisplay:locale.money(s.stake),minStake:s.minStake,maxStake:s.maxStake,stakes:s.stakes,stake:s.stake,turboSpeed:s.speed,turboSpeeds:regional.speeds,turboDisabled:!regional.profile.turbo,autoplayActive:s.autoplayActive,autoplayRemaining:s.remaining,infiniteAvailable:false,autoplaySettings:{basic:false,specialAvailable:false,roundChoices:[10,25,50,100].filter(n=>n<=regional.autoMax)},stakeColumns:3,stakePlacement:'above',disabled:!s.ready||s.openingPending,playDisabled:s.busy||s.autoplayActive||s.winOpen,stakeDisabled:s.busy||s.autoplayActive||s.winOpen,autoplayDisabled:!regional.autoMax||(s.busy||s.winOpen)&&!s.autoplayActive};
 const key=JSON.stringify(p)+compact.matches;if(previous!==key){previous=key;controller.setAttribute('name',compact.matches?'game-control-small':'game-control-large');controller.options=p;decorateController(controller)}
 $('shared-controller-dock').hidden=s.replaying;
 const r=s.replayRecord;const cp={balance:locale.money(s.balance),replaying:s.replaying,playing:s.replayPlaying,round:r?.number,stake:locale.money(s.stake),last:$('last-win').textContent,language:locale.settings().language};const ck=JSON.stringify(cp);if(ck!==chromeKey){chromeKey=ck;header.options={type:s.replaying?'session-replay':'default',balance:cp.balance,playing:s.replayPlaying};decorateHeader(header);footer.options=s.replaying&&r?{type:'session-replay',betId:String(r.number),stake:locale.money(r.stake),winnings:locale.money(r.payout),multiplier:(r.payout/r.stake).toFixed(2)+'×',dateTime:new Date(r.timestamp).toLocaleString(locale.locale())}:{'Bet Amount':locale.money(s.stake),'Last Win Amount':cp.last};decorateFooter(footer)}
}
controller.addEventListener('is-action',e=>{if(e.target!==controller)return;const {action,value}=e.detail;if(action==='play')game.play();if(action==='stake-change')game.stake(Number(value));if(action==='turbo')game.speed(value.speed);if(action==='start')void regional.confirmAuto(Number(value.rounds),game.read().stake*(game.read().bonusFactor||1)).then(ok=>{if(ok)game.start(value)});if(action==='stop')game.stop();decorateController(controller);for(const item of controller.shadowRoot.querySelector('dialog is-component[name="action-boxes"]')?.shadowRoot.querySelectorAll('is-component[name="bet-value"]')||[]){item.options={...item.options,label:locale.money(Number(item.options.value))};style(item,'amount-fit',':host .value{font-size:12px;padding-inline:2px}')}for(const d of controller.shadowRoot.querySelectorAll('dialog[open]')){const auto=d.querySelector('is-component[name="autoplay-sheet"]');if(auto)style(auto,'huff-autoplay-stroke',':host .autoplay-sheet{border:var(--stroke-weight-100) solid var(--stroke-color-default);border-radius:var(--border-radius-80);background:var(--surface-background-primary)}');game.panelOpen(true);if(!d.dataset.hostTracked){d.dataset.hostTracked='true';d.addEventListener('close',()=>game.panelOpen(panel.open||opening.open||languageDialog.open))}}if(['play','stake-change','turbo','start','stop'].includes(action)){previous='';sync()}});
header.addEventListener('is-action',e=>{const a=e.detail.action;if(a==='close')game.exitReplay();else if(a==='information')rules();else if(a==='menu')menu()});
window.addEventListener('huff-state',sync);compact.addEventListener('change',sync);
function closePanel(){panel.close();game.panelOpen(opening.open||languageDialog.open);sync();panelOpener?.focus?.({preventScroll:true})}
function fitPanel(){if(content.getAttribute('name')==='history/panel')decorateHistory(content);if(content.getAttribute('name')==='how-to-play')decorateHelp(content);if(content.getAttribute('name')==='menu'){for(const c of content.shadowRoot.querySelectorAll('is-component'))style(c,'menu-fit',':host .menu-item{width:240px;min-height:44px}:host .label{white-space:normal}');style(content,'menu-width',':host .menu{width:240px;border:1px solid var(--stroke-color-default)}')}
}
function positionPanel(){if(!panel.open||panel.dataset.kind!=='menu')return;const r=header.shadowRoot.querySelector('[data-action="menu"]').getBoundingClientRect();panel.style.left=Math.max(8,Math.min(innerWidth-panel.offsetWidth-8,r.right-panel.offsetWidth))+'px';panel.style.top=Math.min(r.bottom+8,innerHeight-panel.offsetHeight-8)+'px'}
function openPanel(name,options){panelOpener=header.shadowRoot.querySelector('[data-action="'+(name==='how-to-play'?'information':'menu')+'"]');panel.dataset.kind=name;panel.style.left='';panel.style.top='';panel.setAttribute('aria-label',name==='history/panel'?'Bet History':name==='how-to-play'?'How to Play':'Game menu');content.setAttribute('name',name);content.options=options;fitPanel();game.panelOpen(true);if(!panel.open)panel.showModal();positionPanel();content.shadowRoot.querySelector('button')?.focus()}
panel.addEventListener('cancel',e=>{e.preventDefault();closePanel()});panel.addEventListener('click',e=>{if(e.target!==panel)return;const r=panel.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closePanel()});window.addEventListener('resize',positionPanel);
function menu(tools=false){const s=game.read();openPanel('menu',{sound:s.sound,music:s.music,bonusFeatures:regional.bonusEnabled,items:tools?[{label:'Back',icon:'arrow left',action:'back'},{label:'Jurisdiction',icon:'menu',action:'jurisdiction'},{label:regional.bonusLabel,icon:'menu',switch:true,key:'bonusFeatures'},{label:'Language & currency',icon:'menu',action:'locale'},{label:'Restart onboarding',icon:'tutorial',action:'tutorial'},{label:'Outcomes',icon:'info',action:'outcomes'},{label:'Game tuning & RTP',icon:'info',action:'tuning'},{label:'Win previews',icon:'tutorial',action:'wins'},{label:'Toggle fullscreen',icon:'menu',action:'fullscreen'},{label:'Reset demo balance',icon:'user-history',action:'reset'}]:[{label:'How to play',icon:'info',action:'information'},{label:'Tutorial',icon:'tutorial',action:'tutorial'},{label:'Bet History',icon:'user-history',action:'history'},{label:'Music',icon:'music',switch:true,key:'music'},{label:'Sound Effects',icon:'sound-effects',switch:true,key:'sound'},{label:'Language & currency',icon:'menu',action:'locale'},{label:'Prototype settings',icon:'menu',action:'settings'}]})}
function historyPanel(){if(game.read().autoplayActive)game.stop();const rows=game.rounds().map(r=>({key:String(r.number),id:String(r.number),date:new Date(r.timestamp).toLocaleDateString(locale.locale()),time:new Date(r.timestamp).toLocaleTimeString(locale.locale()),bet:locale.money(r.stake),win:locale.money(r.payout),status:r.payout>0?'win':'loss',multiplier:r.multiplier.toFixed(2)+'×',difficulty:'—',balanceBefore:locale.money(r.balanceBefore),balanceAfter:locale.money(r.balanceAfter),freeCreditBefore:'—',freeCreditAfter:'—'}));openPanel('history/panel',{contentState:'replay',search:'no',rows,expandedKey:null,guidance:'Your last 60 settled demo rounds in this session. Replays do not use or award credits.'})}
function rules(){const s=game.read();openPanel('how-to-play',{title:'How to Play',sections:[{title:'Step up to the plate',paragraphs:['Choose your bet and press Play. Straw, Wood or Brick Pig is selected randomly for its animation style. A missed swing ends the round with no win.']},{title:'Build your return',paragraphs:['Hard hats marked 1, 2, 5 and 10 add bet multiples. x2, x3, x4 and x5 multiply the running total. Positive pickups lift the pig upward.']},{title:'Watch the hazards',paragraphs:['Seagulls halve the running total and knock the pig downward. Landing in the woodland pond or hitting a broken tree stump ends the round with no return.']},{title:'Land and collect',paragraphs:['Stop safely on the grass to collect the final return. Maximum win is 100× bet. Turbo changes playback speed only.']},{title:'Autoplay and history',paragraphs:['Choose a fixed number of rounds and optional loss, profit or single-win limits. Stop autoplay at any time; an accepted round finishes. Bet History holds your last 60 settled rounds for this session, with replays.']}],limits:[['Bet Limits',locale.money(s.minStake),locale.money(s.maxStake)],['Multiplier','0×','100×']],notes:[`Theoretical RTP: ${s.rtp.toFixed(2)}%. Each outcome is selected before its animation. Game tuning changes future rounds.`,'Demo credits only. This prototype is not certified.']})}
content.addEventListener('is-action',e=>{const {action,value}=e.detail;fitPanel();if(action==='close')closePanel();else if(action==='information')rules();else if(action==='history')historyPanel();else if(action==='replay'){closePanel();game.replay(Number(value.betId))}else if(action==='toggle'){if(value.key==='bonusFeatures'){const error=regional.setBonusEnabled(value.checked);menu(true);const note=document.createElement('p');note.setAttribute('role','status');note.textContent=error||'This game currently has no bonus-buy features.';content.shadowRoot.append(note)}else game[value.key]?.(value.checked);}else if(action==='settings')menu(true);else if(action==='jurisdiction'){closePanel();regional.open();}else if(action==='back')menu();else if(action==='locale'){closePanel();openLanguage()}else if(action==='tutorial'){if(game.read().busy||game.read().replaying)return;game.stop();closePanel();tutorial()}else if(['outcomes','tuning','wins','fullscreen','reset'].includes(action)){if(game.read().replaying)return;closePanel();game.tool(action)}});
const languageDialog=document.createElement('dialog');languageDialog.className='locale-dialog';languageDialog.setAttribute('aria-label','Language & currency');languageDialog.innerHTML=`<form method="dialog"><h2>Language & currency</h2><label>Language<select id="game-language">${locale.languages.map(l=>`<option value="${l.code}">${l.label}</option>`).join('')}</select></label><label>Currency<select id="game-currency">${locale.currencies.map(c=>`<option>${c}</option>`).join('')}</select></label><p>Draft translations for testing. Changing currency resets your demo balance and history. Demo presets are not exchange rates.</p><p role="status" id="locale-status"></p><div class="locale-actions"><button value="cancel">Cancel</button><button type="button" id="apply-locale">Apply</button></div></form>`;document.body.append(languageDialog);
function openLanguage(){languageDialog.querySelector('#game-language').value=locale.settings().language;languageDialog.querySelector('#game-currency').value=locale.settings().currency;languageDialog.querySelector('#locale-status').textContent='';game.panelOpen(true);languageDialog.showModal()}
languageDialog.addEventListener('close',()=>{game.panelOpen(opening.open);panelOpener?.focus?.()});languageDialog.querySelector('#apply-locale').onclick=()=>{const s=game.read();if(s.busy||s.autoplayActive||s.replaying||s.winOpen){languageDialog.querySelector('#locale-status').textContent='Finish the round, stop autoplay and exit replay first.';return}const old=locale.settings(),next={language:languageDialog.querySelector('#game-language').value,currency:languageDialog.querySelector('#game-currency').value};locale.configure(next);if(old.currency!==next.currency)game.setCurrency(locale.preset());document.documentElement.lang=locale.locale();game.refreshLocale();previous=chromeKey='';sync();languageDialog.close()};
